public class Shipping
{
    private readonly ICarrier _carrier;
    public Shipping(ICarrier carrier) => _carrier = carrier;

    public decimal Rate(decimal orderTotal) =>
        orderTotal > 50m ? 0m : _carrier.BaseRate();
}

