public class LoyaltyDiscountTests
{
    [Theory]
    [InlineData(0, 200, 0)]
    [InlineData(3, 200, 10)]
    [InlineData(10, 200, 20)]
    public void Discount_DependsOnFullYears(int years, decimal price, decimal expected)
    {
        var discount = new LoyaltyDiscount().For(years, price);   // Act
        Assert.Equal(expected, discount);                          // Assert
    }
}

public class LoyaltyDiscount
{
    public decimal For(int years, decimal price) =>
        years >= 10 ? price * 0.10m : years >= 3 ? price * 0.05m : 0m;
}
